#!/usr/bin/env python3
"""Patch and verify Android files generated by `flutter create` for M-TIER."""

from __future__ import annotations

import re
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / "android/app/src/main/AndroidManifest.xml"
GRADLE_CANDIDATES = [
    ROOT / "android/app/build.gradle.kts",
    ROOT / "android/app/build.gradle",
]
APPLICATION_ID = "com.mtier.app"
ANDROID_NS = "http://schemas.android.com/apk/res/android"
ET.register_namespace("android", ANDROID_NS)


def fail(message: str) -> None:
    print(f"patch_android.py: ERROR: {message}", file=sys.stderr)
    raise SystemExit(1)


def find_default_config_block(source: str) -> tuple[int, int]:
    match = re.search(r"\bdefaultConfig\s*\{", source)
    if not match:
        fail("bloc defaultConfig introuvable dans le fichier Gradle Android.")
    opening = source.find("{", match.start())
    depth = 0
    quote: str | None = None
    escaped = False
    line_comment = False
    block_comment = False
    index = opening
    while index < len(source):
        char = source[index]
        next_char = source[index + 1] if index + 1 < len(source) else ""
        if line_comment:
            if char == "\n":
                line_comment = False
        elif block_comment:
            if char == "*" and next_char == "/":
                block_comment = False
                index += 1
        elif quote:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
        elif char == "/" and next_char == "/":
            line_comment = True
            index += 1
        elif char == "/" and next_char == "*":
            block_comment = True
            index += 1
        elif char in ("'", '"'):
            quote = char
        elif char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return opening, index
        index += 1
    fail("bloc defaultConfig non fermé dans le fichier Gradle Android.")
    raise AssertionError("unreachable")


def patch_gradle(path: Path) -> None:
    source = path.read_text(encoding="utf-8")
    opening, closing = find_default_config_block(source)
    block = source[opening + 1 : closing]
    is_kotlin = path.name.endswith(".kts")
    if is_kotlin:
        pattern = r"(?m)^(\s*)applicationId\s*=\s*(['\"])[^'\"]*\2\s*$"
        replacement = rf'\1applicationId = "{APPLICATION_ID}"'
    else:
        pattern = r"(?m)^(\s*)applicationId\s+(['\"])[^'\"]*\2\s*$"
        replacement = rf'\1applicationId "{APPLICATION_ID}"'
    updated, count = re.subn(pattern, replacement, block, count=1)
    if count == 0:
        indent_match = re.search(r"\n(\s*)\S", block)
        indent = indent_match.group(1) if indent_match else "        "
        line = (
            f'\n{indent}applicationId = "{APPLICATION_ID}"\n'
            if is_kotlin
            else f'\n{indent}applicationId "{APPLICATION_ID}"\n'
        )
        updated = block + line
    result = source[: opening + 1] + updated + source[closing:]
    path.write_text(result, encoding="utf-8")

    check = path.read_text(encoding="utf-8")
    _, check_end = find_default_config_block(check)
    check_open = check.find("{", re.search(r"\bdefaultConfig\s*\{", check).start())
    check_block = check[check_open + 1 : check_end]
    if APPLICATION_ID not in check_block:
        fail(f"applicationId {APPLICATION_ID} absent après modification de {path}.")


def patch_manifest() -> None:
    if not MANIFEST.is_file():
        fail(f"manifeste Android principal introuvable : {MANIFEST.relative_to(ROOT)}. Lancez flutter create . --platforms=android d'abord.")
    try:
        tree = ET.parse(MANIFEST)
    except ET.ParseError as error:
        fail(f"manifeste Android invalide : {error}")
    root = tree.getroot()
    permission_tag = "uses-permission"
    permission_name = f"{{{ANDROID_NS}}}name"
    internet = "android.permission.INTERNET"
    if not any(
        child.tag == permission_tag and child.get(permission_name) == internet
        for child in root
    ):
        permission = ET.Element(permission_tag)
        permission.set(permission_name, internet)
        application = root.find("application")
        if application is None:
            fail("élément <application> absent du manifeste Android.")
        root.insert(list(root).index(application), permission)
    application = root.find("application")
    if application is None:
        fail("élément <application> absent du manifeste Android.")
    application.set(f"{{{ANDROID_NS}}}label", "M-TIER")
    tree.write(MANIFEST, encoding="utf-8", xml_declaration=True)

    verified = ET.parse(MANIFEST).getroot()
    has_internet = any(
        child.tag == permission_tag and child.get(permission_name) == internet
        for child in verified
    )
    verified_application = verified.find("application")
    if not has_internet:
        fail("la permission INTERNET n'apparaît pas dans le manifeste après modification.")
    if verified_application is None or verified_application.get(f"{{{ANDROID_NS}}}label") != "M-TIER":
        fail("le nom affiché M-TIER n'a pas été appliqué au manifeste.")


def main() -> None:
    gradle = next((path for path in GRADLE_CANDIDATES if path.is_file()), None)
    if gradle is None:
        fail("android/app/build.gradle(.kts) introuvable. La génération Android a-t-elle réussi ?")
    patch_gradle(gradle)
    patch_manifest()
    print(
        "OK: Android vérifié — INTERNET présent dans le manifeste principal, "
        f"label M-TIER et applicationId {APPLICATION_ID}."
    )


if __name__ == "__main__":
    main()
